use super::super::equipment_tables::{EquipmentCategory, EquipmentTableEntry};

pub const MAGIC_ITEMS_TABLE: &[EquipmentTableEntry] = &[
    EquipmentTableEntry { key: "Amazing Tools of Manufacture", category: EquipmentCategory::MagicItems, name: "Amazing Tools of Manufacture", cost_gp: Some(12000.0), weight_lbs: Some(1.0), description: Some("In the hands of a casual wielder, these items simply appear to be magically enhanced masterwork tools for a specific Craft skill (determined randomly), granting a +4 circumstance bonus on such skill checks. However, in the hands of a craftsman with 6 or more ranks in the selected Craft skill, the wielder can perform 2,000 gp worth of work in a single hour, but only once each day. Only a single skill check is required to successfully complete the item, made on the last day of crafting and gaining the +4 circumstance bonus granted by the tools.") },
    EquipmentTableEntry { key: "Amulet of Channeled Life", category: EquipmentCategory::MagicItems, name: "Amulet of Channeled Life", cost_gp: Some(12000.0), weight_lbs: Some(0.5), description: Some("When targeted by positive energy that heals living creatures, the wearer instead gains half the hit points the positive energy heals as temporary hit points. These temporary hit points go away after 10 minutes. This effect does not stack with life channel (see below) or other effects that convert healing positive energy to temporary hit points. Only a living creature can benefit from this amulet; it provides no benefit to undead.") },
    EquipmentTableEntry { key: "Amulet of Hidden Light", category: EquipmentCategory::MagicItems, name: "Amulet of Hidden Light", cost_gp: Some(9000.0), weight_lbs: None, description: Some("Can, on command, shed light as a sunrod. Unlike a normal light source, creatures outside this area cannot see the amulet's light.") },
    EquipmentTableEntry { key: "Ancestral Clasp", category: EquipmentCategory::MagicItems, name: "Ancestral Clasp", cost_gp: Some(10000.0), weight_lbs: Some(0.5), description: Some("Whenever a half-elf fits an ancestral clasp to the pommel, grip, or haft of a longbow, longsword, rapier, or shortbow, the character is treated as though she were proficient with that weapon. In addition, when an ancestral clasp is fitted to any weapon with the word \"elven\" in the title, the character treats the weapon as if it were a martial weapon, mirroring the Weapon Familiarity elven racial trait. A half-elf who already is proficient with one of the above weapons adorned with an ancestral clasp receives a +1 insight bonus on attack rolls with that weapon.") },
    EquipmentTableEntry { key: "Bag of Shadow Clouds", category: EquipmentCategory::MagicItems, name: "Bag of Shadow Clouds", cost_gp: Some(30240.0), weight_lbs: Some(1.0), description: Some("Three times per day, as a move action, the bearer can reach within the bag and pull out 1d4 semi-solid shards of shadow. The bag's bearer can use each shard of shadow as a thrown weapon targeting a single 5-foot square. When it hits, it acts as a Darkness spell, but only affecting one 5-foot square") },
    EquipmentTableEntry { key: "Belt of Foraging", category: EquipmentCategory::MagicItems, name: "Belt of Foraging", cost_gp: Some(6000.0), weight_lbs: Some(1.0), description: Some("As long as the wearer has at least 1 rank in Survival, he need not make a check to get along in the wild; he always succeeds at that Survival check as long as he moves at half his overland speed. He can still choose to make that check to provide food and water for one other creature for every 2 points by which his result exceeds DC 10. Furthermore, he can instead make a DC 20 Survival check to get along in the wild while moving at full speed instead of half speed. While doing so, he can provide food and water for one other creature for every 2 points by which his check result exceeds 20.") },
    EquipmentTableEntry { key: "Belt of Stoneskin", category: EquipmentCategory::MagicItems, name: "Belt of Stoneskin", cost_gp: Some(60000.0), weight_lbs: Some(10.0), description: Some("Every 24 hours, the belt's wearer gains DR 10/adamantine until the belt absorbs 100 points of damage. It must worn for 24 consecutive hours in order for its magic to take effect.") },
    EquipmentTableEntry { key: "Black Feather Fan", category: EquipmentCategory::MagicItems, name: "Black Feather Fan", cost_gp: Some(10000.0), weight_lbs: Some(1.0), description: Some("The bearer can create a Gust of Wind, Whispering Wind, or Wind Wall up to 3 times per day, in any combination.") },
    EquipmentTableEntry { key: "Bonebreaker Gauntlets", category: EquipmentCategory::MagicItems, name: "Bonebreaker Gauntlets", cost_gp: Some(6000.0), weight_lbs: Some(2.0), description: Some("Once per day, as part of a melee attack, the wearer can activate the gauntlets to inflict a horrific injury on an opponent. If the attack hits, the target must make a DC 14 Will save. If the save fails, the gauntlets reduce the target's Strength, Dexterity, or Constitution (wearer's choice) by -6.") },
    EquipmentTableEntry { key: "Book of Marvelous Recipes", category: EquipmentCategory::MagicItems, name: "Book of Marvelous Recipes", cost_gp: Some(28800.0), weight_lbs: Some(3.0), description: Some("Allows reader to use the Profession (cook) skill untrained, or grants a +4 competence bonus if trained. Once per day, Heroes' Feast (caster level 11th).") },
    EquipmentTableEntry { key: "Boots of Escape", category: EquipmentCategory::MagicItems, name: "Boots of Escape", cost_gp: Some(8000.0), weight_lbs: Some(1.0), description: Some("Once per day, when the wearer of the boots is grappled, pinned, or entangled, he may transfer himself to any spot within 30 feet. This acts as if the wearer had used a dimension door spell. A gnome wearing these boots may instead transfer himself up to 400 feet.") },
    EquipmentTableEntry { key: "Bracers of Sworn Vengeance", category: EquipmentCategory::MagicItems, name: "Bracers of Sworn Vengeance", cost_gp: Some(25000.0), weight_lbs: Some(1.0), description: Some("Once per day, as an immediate action when the wearer takes hit point damage from a target, she may cry out, \"Death to those who wrong me!\", swearing vengeance against the attacker. The wearer gains a +1 competence bonus on weapon attack rolls made against the target of his sworn vengeance, and deals an additional 2d6 points of damage on successful weapon attack rolls.") },
    EquipmentTableEntry { key: "Brooch of Blending", category: EquipmentCategory::MagicItems, name: "Brooch of Blending", cost_gp: Some(2000.0), weight_lbs: None, description: Some("As a standard action the wearer can transform his features to appear either entirely elven or entirely human. Grants a +20 circumstance bonus on Disguise checks to appear as a member of the selected race. Those who know him recognize him without a Perception check. This change does not radiate magic and cannot be seen with detect magic, although true seeing does reveal the alteration. This item only functions for half-elves.") },
    EquipmentTableEntry { key: "Bubble Vault", category: EquipmentCategory::MagicItems, name: "Bubble Vault", cost_gp: Some(1500.0), weight_lbs: None, description: Some("Swells to form a 1-foot-diameter soap-like bubble when placed in water. Up to 5 cubic feet of goods can be placed inside. On command, the bubble sinks to the bottom of the water, automatically burying itself 1 foot deep if there is mud or other loose material present.") },
    EquipmentTableEntry { key: "Cap of Human Guise", category: EquipmentCategory::MagicItems, name: "Cap of Human Guise", cost_gp: Some(800.0), weight_lbs: None, description: Some("Allows its wearer to alter her appearance as with a disguise self spell, except she can only appear as a plainly dressed Small human child, adult halfling, or adult gnome.") },
    EquipmentTableEntry { key: "Cat's Eye Crown", category: EquipmentCategory::MagicItems, name: "Cat's Eye Crown", cost_gp: Some(18000.0), weight_lbs: Some(1.0), description: Some("Decorated with a single cat's eye gemstone as a centerpiece. When the gem is attached to the crown, its wearer gains darkvision 60 feet, or increases her darkvision by 60 feet if she already possesses that sense. The gemstone is detachable, and can be rolled into rooms, dropped into holes, thrown through windows, or planted on a creature. Once per day, on command, the crown's wearer gains the benefit of the clairaudience/clairvoyance spell, but uses the cat's eye gemstone as that spell's sensor and gains darkvision when viewing through that sensor. If the stone is held or carried by a creature, even within a sack or some other container, the creature wearing the crown uses the senses of the creature carrying the gemstone as the sensor instead.") },
    EquipmentTableEntry { key: "Cloak of Fangs", category: EquipmentCategory::MagicItems, name: "Cloak of Fangs", cost_gp: Some(2800.0), weight_lbs: Some(1.0), description: Some("Wearing the cloak grants a +1 resistance bonus on saving throws. Furthermore, the wearer can force its teeth to grow rapidly up to five times per day as a swift action. The oversized teeth last for 1 round, during which time the wearer can make a bite attack. Treat this attack as a primary natural attack that deals 1d4 points of damage (or 1d6 if the wearer is Medium). If the wearer already has a bite attack, the damage of that bite attack increases by one step.") },
    EquipmentTableEntry { key: "Cloak of Fiery Vanishing", category: EquipmentCategory::MagicItems, name: "Cloak of Fiery Vanishing", cost_gp: Some(2600.0), weight_lbs: Some(1.0), description: Some("Once per day, when subject to an effect that deals fire damage, the wearer can spend an immediate action while obscured by the flames to become invisible, leaving behind an illusory pile of ashes and bones, as if he had been slain by the fire effect.") },
    EquipmentTableEntry { key: "Cloak of Human Guise", category: EquipmentCategory::MagicItems, name: "Cloak of Human Guise", cost_gp: Some(900.0), weight_lbs: Some(1.0), description: Some("Only affects half-humans.  Alters the wearer's appearance similarly to a hat of disguise, but only to the extent that it conceals or alters the wearer's non-human physical traits so the creature appears fully human.") },
    EquipmentTableEntry { key: "Cloak of the Diplomat", category: EquipmentCategory::MagicItems, name: "Cloak of the Diplomat", cost_gp: Some(20000.0), weight_lbs: Some(1.0), description: Some("Once per day, before making a Diplomacy or Sense Motive check, the wearer can roll twice and take the better result. The wearer can adjust a creature's attitude up to three steps when using Diplomacy. However,should the wearer ever fail a Diplomacy check to adjust a creature's attitude by 5 or more, the creature's attitude is reduced by two steps instead of one.") },
    EquipmentTableEntry { key: "Cloak of the Scuttling Rat", category: EquipmentCategory::MagicItems, name: "Cloak of the Scuttling Rat", cost_gp: Some(6000.0), weight_lbs: Some(1.0), description: Some("Changes the wearer into a dire rat as per Beast Shape I up to 5 minutes per day.") },
    EquipmentTableEntry { key: "Corset of the Vishkanya", category: EquipmentCategory::MagicItems, name: "Corset of the Vishkanya", cost_gp: Some(3000.0), weight_lbs: Some(1.0), description: Some("The wearer can compress herself to fit through tight spaces as though affected by a Squeeze spell for up to 10 rounds per day. While using the corset's magic, she gains a +5 bonus on Escape Artist checks.") },
    EquipmentTableEntry { key: "Crown of Conquest", category: EquipmentCategory::MagicItems, name: "Crown of Conquest", cost_gp: Some(24600.0), weight_lbs: Some(3.0), description: Some("Whenever a critical hit is confirmed, the crown creates a prayer effect centered on the crown's wearer (caster level 5th).; Any follower or cohort of the wearer gains a +1 bonus on attack rolls and saving throws against fear effects while within line of sight of the wearer.") },
    EquipmentTableEntry { key: "Crown of Swords", category: EquipmentCategory::MagicItems, name: "Crown of Swords", cost_gp: Some(6000.0), weight_lbs: Some(3.0), description: Some("Can be used up to 10 times per day. When struck in combat, the wearer may spend one use as an immediate action to create a longsword-shaped spiritual weapon that then attacks her attacker. On the wearer's next turn, she may spend one additional use each round to continue attacking that target with the spiritual weapon; the spiritual weapon cannot be redirected and disappears if the target is killed or moves out of range. Multiple spiritual weapons may be created (even attacking the same target) if the wearer is attacked in subsequent rounds.") },
    EquipmentTableEntry { key: "Daredevil Softpaws", category: EquipmentCategory::MagicItems, name: "Daredevil Softpaws", cost_gp: Some(1400.0), weight_lbs: Some(1.0), description: Some("As a free action, the wearer can click her heels together to grant herself a +5 competence bonus on Acrobatics checks made to move through threatened squares or to move through an enemy's space without provoking attacks of opportunity for up to 10 rounds per day. The rounds need not be consecutive. Furthermore, anytime the wearer of the boots successfully moves though the space of an enemy without provoking an attack of opportunity, she gains a +2 bonus on attack rolls against that enemy until the end of her turn.") },
    EquipmentTableEntry { key: "Darksire Amulet", category: EquipmentCategory::MagicItems, name: "Darksire Amulet", cost_gp: Some(9000.0), weight_lbs: Some(1.0), description: Some("When worn by a tiefling with cold, electricity, or fire resistance, increases that resistance by 5. Provides a +4 insight bonus on Diplomacy skill checks made to influence evil outsiders.") },
    EquipmentTableEntry { key: "Elixir of Darksight", category: EquipmentCategory::MagicItems, name: "Elixir of Darksight", cost_gp: Some(1200.0), weight_lbs: None, description: Some("Enables user to see through Deeper Darkness when using Darkvision") },
    EquipmentTableEntry { key: "Elixir of Forceful Exhalation", category: EquipmentCategory::MagicItems, name: "Elixir of Forceful Exhalation", cost_gp: Some(900.0), weight_lbs: Some(1.0), description: Some("The drinker can exhale up to three 15-foot-long Gusts of Wind (as the spell), after which the skill bonuses end.") },
    EquipmentTableEntry { key: "Escape Dust", category: EquipmentCategory::MagicItems, name: "Escape Dust", cost_gp: Some(300.0), weight_lbs: None, description: Some("Requires a ranged touch attack by its user (with a range increment of 5 feet), but doing so does not provoke attacks of opportunity. On a hit, the target is dazzled and cannot make attacks of opportunity or immediate actions for 1 round.") },
    EquipmentTableEntry { key: "Fetish Mask", category: EquipmentCategory::MagicItems, name: "Fetish Mask", cost_gp: Some(0.0), weight_lbs: None, description: Some("A Scarred Witch Doctor forms a bond with a wooden mask.") },
    EquipmentTableEntry { key: "Figurine of Wondrous Power (Black Jade Raven)", category: EquipmentCategory::MagicItems, name: "Figurine of Wondrous Power (Black Jade Raven)", cost_gp: Some(9100.0), weight_lbs: Some(1.0), description: Some("Can be used up to 24 hours per week. After three transformations into its giant raven form (though not its smaller version), the statuette loses all magical properties.") },
    EquipmentTableEntry { key: "Gauntlets of Skill at Arms", category: EquipmentCategory::MagicItems, name: "Gauntlets of Skill at Arms", cost_gp: Some(30302.0), weight_lbs: Some(1.0), description: Some("The guantlets enable the wearer to use any traditional elven weapon as if he were proficient in its use. If he uses such a weapon and is already proficient with it, he gains a +1 competence bonus on attack and damage rolls.") },
    EquipmentTableEntry { key: "Gloves of Elvenkind", category: EquipmentCategory::MagicItems, name: "Gloves of Elvenkind", cost_gp: Some(7500.0), weight_lbs: None, description: Some("Grant a +5 competence bonus on Spellcraft checks and concentration checks made to cast a spell defensively.") },
    EquipmentTableEntry { key: "Halo of Inner Calm", category: EquipmentCategory::MagicItems, name: "Halo of Inner Calm", cost_gp: Some(16000.0), weight_lbs: Some(1.0), description: Some("Grants the wearer a +4 resistance bonus on saving throws against all spells with the emotion descriptor. When worn by a tiefling of a good alignment, it provides spell resistance 13 against spells with the evil descriptor and a +2 sacred bonus on saving throws.") },
    EquipmentTableEntry { key: "Halo of Menace", category: EquipmentCategory::MagicItems, name: "Halo of Menace", cost_gp: Some(84000.0), weight_lbs: Some(1.0), description: Some("Constantly radiates a 20-foot-radius aura from its wearer. Any hostile creature within the aura must succeed at a DC 20 Will save or take a -2 penalties on attack rolls, saving throws, and AC for the next 24 hours or until it hits the wearer with an attack or damages it with a spell, spell-like ability, or supernatural ability. Chaotic creatures take a -2 penalty on this saving throw. A creature that has resisted or broken the effect of the halo of menace cannot be affected by the same wearer's aura for 24 hours. The aura is a mind-affecting effect.") },
    EquipmentTableEntry { key: "Hobgoblin Battle Standard of Despair", category: EquipmentCategory::MagicItems, name: "Hobgoblin Battle Standard of Despair", cost_gp: Some(50000.0), weight_lbs: Some(3.0), description: Some("A battle standard may be carried (on foot or mounted) or planted. In the latter case, the standard does not need a bearer, but if it is toppled or touched by an enemy, it loses its effectiveness until reclaimed and replanted by allies of its owner.Enemies are sickened while within 60 feet of the banner. Any enemy that sustains a critical hit while sickened because of the standard must succeed at a Will saving throw (DC 15) or become dazed for 1 round.") },
    EquipmentTableEntry { key: "Hobgoblin Battle Standard of Ferocity", category: EquipmentCategory::MagicItems, name: "Hobgoblin Battle Standard of Ferocity", cost_gp: Some(60000.0), weight_lbs: Some(3.0), description: Some("A battle standard may be carried (on foot or mounted) or planted. In the latter case, the standard does not need a bearer, but if it is toppled or touched by an enemy, it loses its effectiveness until reclaimed and replanted by allies of its owner. Allies gain a +2 morale bonus on attack rolls, weapon damage rolls, and saving throws against mind-affecting effects as long as they are within 60 feet of the banner.") },
    EquipmentTableEntry { key: "Hobgoblin Battle Standard of Iron Resolve", category: EquipmentCategory::MagicItems, name: "Hobgoblin Battle Standard of Iron Resolve", cost_gp: Some(45000.0), weight_lbs: Some(3.0), description: Some("A battle standard may be carried (on foot or mounted) or planted. In the latter case, the standard does not need a bearer, but if it is toppled or touched by an enemy, it loses its effectiveness until reclaimed and replanted by allies of its owner. Allies gain 10 temporary hit points and the benefits of the Diehard feat for as long as they are within 30 feet of the banner. The temporary hit points can only be gained once per day per creature.") },
    EquipmentTableEntry { key: "Horseshoes of Crushing Blows +1", category: EquipmentCategory::MagicItems, name: "Horseshoes of Crushing Blows +1", cost_gp: Some(4000.0), weight_lbs: Some(4.0), description: Some("Grant an enhancement bonus to hoof attacks.") },
    EquipmentTableEntry { key: "Horseshoes of Crushing Blows +2", category: EquipmentCategory::MagicItems, name: "Horseshoes of Crushing Blows +2", cost_gp: Some(16000.0), weight_lbs: Some(4.0), description: Some("Grant an enhancement bonus to hoof attacks.") },
    EquipmentTableEntry { key: "Horseshoes of Crushing Blows +3", category: EquipmentCategory::MagicItems, name: "Horseshoes of Crushing Blows +3", cost_gp: Some(36000.0), weight_lbs: Some(4.0), description: Some("Grant an enhancement bonus to hoof attacks.") },
    EquipmentTableEntry { key: "Horseshoes of Crushing Blows +4", category: EquipmentCategory::MagicItems, name: "Horseshoes of Crushing Blows +4", cost_gp: Some(64000.0), weight_lbs: Some(4.0), description: Some("Grant an enhancement bonus to hoof attacks.") },
    EquipmentTableEntry { key: "Horseshoes of Crushing Blows +5", category: EquipmentCategory::MagicItems, name: "Horseshoes of Crushing Blows +5", cost_gp: Some(100000.0), weight_lbs: Some(4.0), description: Some("Grant an enhancement bonus to hoof attacks.") },
    EquipmentTableEntry { key: "Incense of Many Fates", category: EquipmentCategory::MagicItems, name: "Incense of Many Fates", cost_gp: Some(3300.0), weight_lbs: Some(1.0), description: Some("Functions like Legend Lore, but only works if the subject is at hand. Takes 1 hour or 24 hours for non-Samsarans") },
    EquipmentTableEntry { key: "Kitsune Star Gem (1st)", category: EquipmentCategory::MagicItems, name: "Kitsune Star Gem (1st)", cost_gp: Some(750.0), weight_lbs: None, description: Some("Acts as pearl of power, except it only allows a kitsune to recover a spent use of a spell-like ability of the appropriate spell level.") },
    EquipmentTableEntry { key: "Kitsune Star Gem (2nd)", category: EquipmentCategory::MagicItems, name: "Kitsune Star Gem (2nd)", cost_gp: Some(3000.0), weight_lbs: None, description: Some("Acts as pearl of power, except it only allows a kitsune to recover a spent use of a spell-like ability of the appropriate spell level.") },
    EquipmentTableEntry { key: "Kitsune Star Gem (3rd)", category: EquipmentCategory::MagicItems, name: "Kitsune Star Gem (3rd)", cost_gp: Some(6750.0), weight_lbs: None, description: Some("Acts as pearl of power, except it only allows a kitsune to recover a spent use of a spell-like ability of the appropriate spell level.") },
    EquipmentTableEntry { key: "Lambent Window", category: EquipmentCategory::MagicItems, name: "Lambent Window", cost_gp: Some(20000.0), weight_lbs: Some(2.0), description: Some("When a creature spends at least 1 minute staring into its reflection, If on the Material Plane, shows the corresponding location on the Shadow Plane, along with any creatures at that location. Likewise, when used on the Shadow Plane, shows the corresponding location on the Material Plane. This effect can be used for up to 10 minutes per day, which need not be consecutive.") },
    EquipmentTableEntry { key: "Lantern of Dancing Shadows", category: EquipmentCategory::MagicItems, name: "Lantern of Dancing Shadows", cost_gp: Some(41000.0), weight_lbs: Some(2.0), description: Some("causes the illumination level in a 30-foot radius to move one step toward dim light, from bright light to normal light, from normal light to dim light, or from darkness to dim light. Shadow Conjuration once per day, Ghostbane Dirge once per day.") },
    EquipmentTableEntry { key: "Lenses of Darkness", category: EquipmentCategory::MagicItems, name: "Lenses of Darkness", cost_gp: Some(12000.0), weight_lbs: None, description: Some("These lenses protect the wearer against the effect of sunlight, the daylight spell, or similar light effects.") },
    EquipmentTableEntry { key: "Living Garments", category: EquipmentCategory::MagicItems, name: "Living Garments", cost_gp: Some(5000.0), weight_lbs: Some(2.0), description: Some("On command, can make a number of subtle adjustments to itself, including coloring, fit, and basic design, accommodating and accentuating whatever mood the wearer wishes to convey. It always remains clean, and automatically repairs damage to itself at a rate of 1 hit point per round (hardness 0, 4 hit points).") },
    EquipmentTableEntry { key: "Mask of Stony Demeanor", category: EquipmentCategory::MagicItems, name: "Mask of Stony Demeanor", cost_gp: Some(8000.0), weight_lbs: Some(4.0), description: Some("This mask transforms the wearer's face into a stone statue and its voice into an emotionless monotone. Though it allows the wearer to speak, its facial expressions and voice betray little emotion. At 4th level, a quinggong monk (Ultimate Magic) may select this spell as a ki power costing 1 ki point to activate") },
    EquipmentTableEntry { key: "Meridian Belt", category: EquipmentCategory::MagicItems, name: "Meridian Belt", cost_gp: Some(1000.0), weight_lbs: Some(1.0), description: Some("Allows a creature to wear a magic ring on each foot in addition to the ring on each hand, though only two rings function at any given time.") },
    EquipmentTableEntry { key: "Nagaji Scale Polish", category: EquipmentCategory::MagicItems, name: "Nagaji Scale Polish", cost_gp: Some(1400.0), weight_lbs: Some(0.5), description: Some("Any caster may casts spells into the jar. The creature that applies the paste to its scales gains the ability to cast the imbued spells (assuming it meets the prerequisite). Only a reptilian creature can use the polish.") },
    EquipmentTableEntry { key: "Phantasmal Gem", category: EquipmentCategory::MagicItems, name: "Phantasmal Gem", cost_gp: Some(4000.0), weight_lbs: Some(1.0), description: Some("If a spellcaster holding the phantasmal gem casts an illusion spell with a duration of concentration (or concentration + a number of rounds), the illusion lasts up to an additional 10 rounds after the spellcaster ceases concentrating on it. The spellcaster may end the illusion early as a swift action. The phantasmal gem can be used multiple times in a day, but cannot grant more than a total of 10 additional rounds of illusion spells per day. A gnome using a phantasmal gem can recharge it by expending uses of spell-like abilities gained through the gnome magic racial trait. Each spell-like ability expended as a standard action recharges 1 round of duration to the phantasmal gem (up to a maximum of 10 rounds).") },
    EquipmentTableEntry { key: "Pipes of the Warren Guardian", category: EquipmentCategory::MagicItems, name: "Pipes of the Warren Guardian", cost_gp: Some(6000.0), weight_lbs: None, description: Some("If the possessor learns the proper tune, once per day he can use these pipes to summon 1d4+1 dire rats as if using Summon Monster III. The summoned dire rats also have the swarming racial trait, and count as ratfolk for the purposes of the ratfolk's swarming racial trait.") },
    EquipmentTableEntry { key: "Purifying Pearl", category: EquipmentCategory::MagicItems, name: "Purifying Pearl", cost_gp: Some(19000.0), weight_lbs: None, description: Some("Up to 10 cubic feet of food or drink per day is affected as if a purify food and drink spell had been cast. If placed in the mouth of a creature, the pearl acts as a neutralize poison spell cast on that creature (caster level 10th).") },
    EquipmentTableEntry { key: "Quickfingers Gloves", category: EquipmentCategory::MagicItems, name: "Quickfingers Gloves", cost_gp: Some(2500.0), weight_lbs: None, description: Some("A wearer of these gloves with at least 1 rank in Sleight of Hand can perform such a check as a move action by taking a -10 penalty on the check rather than the normal -20.") },
    EquipmentTableEntry { key: "Red Feather Fan", category: EquipmentCategory::MagicItems, name: "Red Feather Fan", cost_gp: Some(5000.0), weight_lbs: Some(1.0), description: Some("Once per day, the bearer can counterspell a darkness effect or light effect.") },
    EquipmentTableEntry { key: "Ring of Craft Magic", category: EquipmentCategory::MagicItems, name: "Ring of Craft Magic", cost_gp: Some(12000.0), weight_lbs: Some(1.0), description: Some("The wearer of this ring may make a Craft check in place of a Spellcraft check to identify an item that could be created with the Craft skill. The wearer may also expend a spell slot or prepared spell to gain an enhancement bonus equal to the level of the expended spell on a single Craft or Profession check (regardless of the amount of time needed to make the check).") },
    EquipmentTableEntry { key: "Ring of Ferocious Action", category: EquipmentCategory::MagicItems, name: "Ring of Ferocious Action", cost_gp: Some(3000.0), weight_lbs: Some(1.0), description: Some("5 charges, renewed each day. At the start of his turn, if the wearer is staggered, as a free action he may spend a charge to activate the ring and ignore the staggered condition until his next turn.") },
    EquipmentTableEntry { key: "Ring of Rat Fangs", category: EquipmentCategory::MagicItems, name: "Ring of Rat Fangs", cost_gp: Some(5000.0), weight_lbs: None, description: Some("Wearer gains bite attack") },
    EquipmentTableEntry { key: "Ring of Swarming Stabs", category: EquipmentCategory::MagicItems, name: "Ring of Swarming Stabs", cost_gp: Some(6000.0), weight_lbs: None, description: Some("Twice per day, when the wearer is flanking an opponent, he can as a swift action deal an additional 1d6 points of sneak attack damage on a successful melee attack against that opponent.") },
    EquipmentTableEntry { key: "Ring of the Sophisticate", category: EquipmentCategory::MagicItems, name: "Ring of the Sophisticate", cost_gp: Some(11000.0), weight_lbs: None, description: Some("Once per day on command, the wearer can cast either locate creature or locate object. On command, the wearer can instantly know the direction to the nearest tavern, pub, or similar watering hole  within 20 miles of the wearer.") },
    EquipmentTableEntry { key: "Rod of Dwarven Might", category: EquipmentCategory::MagicItems, name: "Rod of Dwarven Might", cost_gp: Some(80000.0), weight_lbs: Some(10.0), description: Some("Increases all AC, attack roll, CMD, CMB, and saving throw bonuses from a dwarf's racial traits by +1. The rod shares the mundane powers of a rod of lordly might, but its magical weapon forms are tailored to dwarven preferences.") },
    EquipmentTableEntry { key: "Rubble Gloves", category: EquipmentCategory::MagicItems, name: "Rubble Gloves", cost_gp: Some(8000.0), weight_lbs: Some(1.0), description: Some("If a creature wearing rubble gloves touches a 5-foot square of stone or earth floor, rubble roils to the surface, making the square difficult terrain.") },
    EquipmentTableEntry { key: "Seafoam Shawl", category: EquipmentCategory::MagicItems, name: "Seafoam Shawl", cost_gp: Some(6000.0), weight_lbs: Some(1.0), description: Some("grants the benefits of the Fins to Feet spell once per day.") },
    EquipmentTableEntry { key: "Shackles of Durance Vile", category: EquipmentCategory::MagicItems, name: "Shackles of Durance Vile", cost_gp: Some(16200.0), weight_lbs: Some(2.0), description: Some("When attached to a humanoid creature as their command word is spoken, they affect their prisoner with a dominate person spell, except that if the prisoner fails its saving throw, the effect lasts for as long as the shackles are attached.") },
    EquipmentTableEntry { key: "Shark Tooth Amulet", category: EquipmentCategory::MagicItems, name: "Shark Tooth Amulet", cost_gp: Some(9000.0), weight_lbs: None, description: Some("The wearer can use melee weapons normally while underwater. Also allows the wearer to make thrown ranged weapon attacks underwater with a -2 penalty on attack rolls and range increment halved.") },
    EquipmentTableEntry { key: "Shawl of Life-Keeping", category: EquipmentCategory::MagicItems, name: "Shawl of Life-Keeping", cost_gp: Some(1000.0), weight_lbs: None, description: Some("Stores up to 10 of the wearer's hp.  If wearer's hp is reduced to -1 or lower, immediately heals the wearer.") },
    EquipmentTableEntry { key: "Slippers of the Triton", category: EquipmentCategory::MagicItems, name: "Slippers of the Triton", cost_gp: Some(56000.0), weight_lbs: Some(1.0), description: Some("Grant water breathing, swim speed of 30 ft or +10 foot enhancement if wearer already has a swim speed.") },
    EquipmentTableEntry { key: "Solidsmoke Pipeweed", category: EquipmentCategory::MagicItems, name: "Solidsmoke Pipeweed", cost_gp: Some(1000.0), weight_lbs: None, description: Some("When smoked in any pipe, a halfling who puffs the pipe as a full-round action can shape the smoke into an object weighing no more than 5 pounds and having a maximum volume of 1 cubic foot.  The halfling can, on following rounds, spend additional full-round actions to increase the object's weight by 2 additional pounds and its volume by another cubic foot. The halfling must succeed at an appropriate Craft check to make a complex item. Objects created by solidsmoke pipeweed last for 24 hours") },
    EquipmentTableEntry { key: "Stonemist Cloak", category: EquipmentCategory::MagicItems, name: "Stonemist Cloak", cost_gp: Some(3500.0), weight_lbs: Some(1.0), description: Some("In rocky or mountainous areas, the wearer gains a +5 competence bonus on Stealth checks. Once per day, the wearer can create an area of fog equivalent to Obscuring Mist.") },
    EquipmentTableEntry { key: "Symbol of Luck", category: EquipmentCategory::MagicItems, name: "Symbol of Luck", cost_gp: Some(6000.0), weight_lbs: Some(1.0), description: Some("Changes shape to match its bearer's holy symbol within an hour of coming into her possession. After that transformation is complete, when this symbol is used by a halfling with the luck or adaptable luck racial trait to channel energy in order to heal, it also grants those healed a +1 luck bonus on saving throws for a number of rounds equal to the number of dice healed by the channel energy.") },
    EquipmentTableEntry { key: "Symbol of Unholy Command", category: EquipmentCategory::MagicItems, name: "Symbol of Unholy Command", cost_gp: Some(8000.0), weight_lbs: Some(1.0), description: Some("When the wielder uses this unholy symbol as a focus for the Command Undead feat, he gains a +1 profane bonus to the DC of that feat. Good creatures of 5 Hit Dice or less that attempt to touch the symbol must make a DC 15 Will save or be shaken for 1 round. Deliberate use of a symbol of unholy command is an evil act.") },
    EquipmentTableEntry { key: "Tengu Drinking Jug", category: EquipmentCategory::MagicItems, name: "Tengu Drinking Jug", cost_gp: Some(1000.0), weight_lbs: Some(2.0), description: Some("Any liquid placed within the jug becomes safe to drink, as though affected by Purify Food and Drink. Three times per day, the bearer can command the jug to alter the temperature of its contents  anywhere from ice cold to boiling hot. Once per day, the bearer can command water placed into the jug to transform into plum liquor, sake, or tea. Holds up to 1 gallon.") },
    EquipmentTableEntry { key: "Trapmaker's Sack", category: EquipmentCategory::MagicItems, name: "Trapmaker's Sack", cost_gp: Some(20000.0), weight_lbs: Some(2.0), description: Some("Once per day as a full-round action, the bearer can command the sack to create any mechanical trap of CR 4 or less, which appears at a designated spot within 50 feet. The bearer must make a Craft (Traps) check with a DC equal to the normal DC for creating the trap.") },
    EquipmentTableEntry { key: "Wound Paste", category: EquipmentCategory::MagicItems, name: "Wound Paste", cost_gp: Some(50.0), weight_lbs: Some(0.5), description: Some("Acts as a stabilize spell when slathered on a dying creature. Contains 5 doses.") },
];
